WITH pos AS (SELECT patient_id, MIN(test_date) AS fp FROM covid_tests WHERE result = 'Positive' GROUP BY patient_id),
neg AS (SELECT t.patient_id, MIN(t.test_date) AS fn FROM covid_tests t JOIN pos ON pos.patient_id = t.patient_id WHERE t.result = 'Negative' AND t.test_date > pos.fp GROUP BY t.patient_id)
SELECT p.patient_id, p.patient_name, p.age, CAST(ROUND(julianday(n.fn) - julianday(o.fp)) AS INTEGER) AS recovery_time FROM patients p JOIN pos o ON o.patient_id = p.patient_id JOIN neg n ON n.patient_id = p.patient_id ORDER BY recovery_time, p.patient_name;

WITH last_event AS (SELECT user_id, event_type, plan_name, monthly_amount, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY event_date DESC, event_id DESC) AS rn FROM subscription_events),
hist AS (SELECT user_id, MIN(event_date) AS start_date, MAX(event_date) AS last_date, MAX(monthly_amount) AS max_amount, SUM(CASE WHEN event_type = 'downgrade' THEN 1 ELSE 0 END) AS downgrades FROM subscription_events GROUP BY user_id)
SELECT l.user_id, l.plan_name AS current_plan, ROUND(l.monthly_amount, 2) AS current_monthly_amount, ROUND(h.max_amount, 2) AS max_historical_amount, CAST(ROUND(julianday(h.last_date) - julianday(h.start_date)) AS INTEGER) AS days_as_subscriber FROM last_event l JOIN hist h ON h.user_id = l.user_id WHERE l.rn = 1 AND l.event_type <> 'cancel' AND h.downgrades >= 1 AND l.monthly_amount < 0.5 * h.max_amount AND (julianday(h.last_date) - julianday(h.start_date)) >= 60 ORDER BY days_as_subscriber DESC, l.user_id;

WITH t AS (SELECT user_id, reaction, COUNT(*) AS cnt FROM reactions GROUP BY user_id, reaction),
s AS (SELECT user_id, MAX(cnt) AS mx, SUM(cnt) AS total FROM t GROUP BY user_id HAVING SUM(cnt) >= 5 AND 5 * MAX(cnt) >= 3 * SUM(cnt))
SELECT s.user_id, t.reaction AS dominant_reaction, ROUND(t.cnt * 1.0 / s.total, 2) AS reaction_ratio FROM s JOIN t ON t.user_id = s.user_id WHERE t.cnt = s.mx ORDER BY reaction_ratio DESC, s.user_id;
